const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log(JSON.stringify(variants, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 2. Check compatibility target: Aurora Smart Desk Lamp Pro (PROD-73FAB4)
const lamp = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('=== COMPATIBLE PRODUCT (PROD-73FAB4) ===');
console.log(JSON.stringify(lamp, null, 2));

// 3. Active electronics promotions
console.log('\n=== ACTIVE PROMOTIONS ===');
const promos = db.prepare(\"SELECT * FROM promotions WHERE active = 1\").all();
console.log(JSON.stringify(promos, null, 2));

// 4. Specifically look for ELEC15
console.log('\n=== PROMO: ELEC15 ===');
const elec15 = db.prepare(\"SELECT * FROM promotions WHERE promo_code = 'ELEC15'\").get();
console.log(JSON.stringify(elec15, null, 2));

// 5. Find user with gold tier and 5623 loyalty points
console.log('\n=== USER (gold tier, 5623 points) ===');
const user = db.prepare(\"SELECT * FROM users WHERE loyalty_tier = 'gold' AND loyalty_points = 5623\").get();
if (user) {
  console.log(JSON.stringify(user, null, 2));
} else {
  // try broader search
  const users = db.prepare(\"SELECT user_id, name, loyalty_tier, loyalty_points FROM users WHERE loyalty_tier LIKE '%gold%' OR loyalty_points = 5623\").all();
  console.log('Exact match not found. Broader search:');
  console.log(JSON.stringify(users, null, 2));
}
"
